mapper.insert:
MERGE INTO ST_TIDE_R t USING (
SELECT #{pojo.STCD} AS STCD, TO_DATE(#{pojo.TM}, 'YYYY-MM-DD HH24:MI:SS') AS TM, #{pojo.TDZ} AS TDZ FROM DUAL
) s ON (t.STCD = s.STCD AND t.TM = s.TM) WHEN MATCHED THEN UPDATE SET t.TDZ = s.TDZ WHEN NOT MATCHED THEN INSERT (STCD, TM, TDZ) VALUES (s.STCD, s.TM, s.TDZ)
